insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009201491', '40000000-0000-4000-8000-000000920149', 'Nomeie o conceito principal antes de avaliar as alternativas.', 1), ('60000000-0000-4000-8000-000009201492', '40000000-0000-4000-8000-000000920149', 'Aplicar a definição diretamente.', 2), ('60000000-0000-4000-8000-000009201493', '40000000-0000-4000-8000-000000920149', 'Compare cada alternativa com a propriedade essencial, não apenas com palavras parecidas.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000920149', 'Permite transferências entre dispositivo e memória com pouca intervenção da CPU.', 'O controlador DMA assume a transferência e sinaliza a conclusão. A alternativa D expressa essa propriedade de modo preciso; as demais trocam o papel de componentes, extrapolam a definição ou descrevem outra técnica.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009201491', '40000000-0000-4000-8000-000000920149', 'Identifique o foco', 'O enunciado trata de barramentos e entrada saida e pede uma interpretação conceitual.', 1), ('70000000-0000-4000-8000-000009201492', '40000000-0000-4000-8000-000000920149', 'Recupere a definição', 'O controlador DMA assume a transferência e sinaliza a conclusão.', 2), ('70000000-0000-4000-8000-000009201493', '40000000-0000-4000-8000-000000920149', 'Aplique ao caso', 'A informação relevante permite concluir: Permite transferências entre dispositivo e memória com pouca intervenção da CPU.', 3), ('70000000-0000-4000-8000-000009201494', '40000000-0000-4000-8000-000000920149', 'Elimine distrações', 'As outras alternativas representam confusões frequentes entre dados, endereço, estado, controle ou desempenho.', 4), ('70000000-0000-4000-8000-000009201495', '40000000-0000-4000-8000-000000920149', 'Verifique a conclusão', 'A resposta permanece coerente com a definição; portanto, a alternativa D é a correta.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000920150', '20000000-0000-4000-8000-000000000005', '10000000-0000-4000-8000-000000001003', 'multiple_choice', 'hard', 'published', 'Considere uma atividade de laboratório sobre arquitetura de computadores. A decisão proposta depende de interpretar a propriedade sem generalizações indevidas. A arbitragem de barramento resolve. Um estudante afirmou a opção destacada. Qual avaliação é adequada?') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
